vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

  vec2 uv2 = vUv;

  // diffused version:
  float ss = 0.1;
  vec3 blur = 0.25*(
    texture(sampler_main, uv2+ss*uTexSize.zw*vec2( 1, 1)).xyz +
    texture(sampler_main, uv2+ss*uTexSize.zw*vec2(-1, 1)).xyz +
    texture(sampler_main, uv2+ss*uTexSize.zw*vec2( 1,-1)).xyz +
    texture(sampler_main, uv2+ss*uTexSize.zw*vec2(-1,-1)).xyz
  );

